var path="Assets/RingTossTutorial/Scenes/RingToss_v0_1.unity";
var current=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(current.path!=path || current.isDirty) throw new System.Exception("Expected saved tutorial scene.");
var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(path);
var roots=scene.GetRootGameObjects();
var ring=roots.First(g=>g.name=="Ring");
var grab=ring.GetComponent<UnityEngine.XR.Interaction.Toolkit.Interactables.XRGrabInteractable>();
var body=ring.GetComponent<Rigidbody>();
var origin=roots.First(g=>g.name=="XR Origin");
var drivers=origin.GetComponentsInChildren<UnityEngine.InputSystem.XR.TrackedPoseDriver>();
var interactors=origin.GetComponentsInChildren<UnityEngine.XR.Interaction.Toolkit.Interactors.XRDirectInteractor>();
var input=origin.GetComponent<UnityEngine.XR.Interaction.Toolkit.Inputs.InputActionManager>();
var all=roots.SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
var missing=all.Sum(t=>UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
bool tracking=drivers.Length==3 && drivers.All(d=>d.positionInput.reference!=null && d.positionInput.reference.action!=null && d.rotationInput.reference!=null && d.rotationInput.reference.action!=null && d.trackingStateInput.reference!=null && d.trackingStateInput.reference.action!=null);
bool select=interactors.Length==2 && interactors.All(i=>i.selectInput.inputActionReferencePerformed!=null && i.selectInput.inputActionReferencePerformed.action!=null && i.selectInput.inputActionReferenceValue!=null && i.selectInput.inputActionReferenceValue.action!=null && i.interactionManager!=null);
bool inputs=input.actionAssets.Count==1 && input.actionAssets[0]!=null;
bool shape=grab.colliders.Count==16 && grab.colliders.All(c=>c!=null && !c.isTrigger) && ring.GetComponent<MeshFilter>().sharedMesh!=null;
var result=new { scene=scene.path, saved=!scene.isDirty, roots=roots.Select(g=>g.name).ToArray(), missingScripts=missing, trackingReferencesValid=tracking, selectReferencesValid=select, inputAssetValid=inputs, ringShapeValid=shape, ringPosition=ring.transform.position.ToString(), ringComponents=ring.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray(), mass=body.mass, gravity=body.useGravity, kinematic=body.isKinematic, collision=body.collisionDetectionMode.ToString(), movement=grab.movementType.ToString(), throwOnDetach=grab.throwOnDetach, colliderCount=grab.colliders.Count, canvases=all.Count(t=>t.GetComponent<Canvas>()!=null), audioSources=all.Count(t=>t.GetComponent<AudioSource>()!=null) };
if(missing!=0 || !tracking || !select || !inputs || !shape) throw new System.Exception(Newtonsoft.Json.JsonConvert.SerializeObject(result));
return result;
